・PTCサーミスタ（正の温度係数）：ある温度を境に抵抗が急増する特殊な特性。過熱保護（自己制御ヒータ等）に利用
・使いどころ：NTCは感度が高く温度検出用、PTCは特定温度での自己保護回路（モータの過熱保護等）に向く

