━━━━━━━━━━━━━━━━━━━━━━
・静電誘導：電力線の電圧により通信線に電圧が誘起（常時も発生、対地静電容量経由）
・電磁誘導：地絡故障時の零相電流により通信線に電圧が誘起（相互インダクタンス経由）★
・対策：ねん架（3相の位置を入れ替え平衡化）・通信線との離隔・遮へい線・中性点の高抵抗化
・ねん架の目的：各相の線路定数を平準化→不平衡と誘導障害を抑制

