━━━━━━━━━━━━━━━━━━━━━━
○意味：新しく発電設備を連系すると、その地点の短絡容量（強さ）が増加し、既設の遮断器の定格遮断容量を超えてしまうことがある
・短絡容量は「電源の数・大きさ」で決まるため、発電設備が増えるほど連系点の短絡容量は増加する傾向★
