・ディジタル形の利点：多機能化（1台で複数保護要素）・整定変更が容易・自己診断機能・故障記録（事故解析に有用）
・伝送技術の発展で、離れた地点の情報を使う保護（電流差動保護など）が実用化しやすくなった

