        id: 'de-09', title: '電力系統の安定度', emoji: '⚖️',
        body: `▼ゼロから：安定度は「大勢で手をつないだまま走り続けられるか」
・多数の発電機が系統でつながり、同じ速度（同期速度）で足並みをそろえて回っている状態が正常運転
・誰か1人（1台の発電機）がつまずくと、隣の人も引きずられて全体のリズムが崩れる恐れがある
・安定度とは「多少のつまずき（外乱）があっても、みんなが再び足並みをそろえられるか」という粘り強さの指標
⚠ 例えの限界：人間と違い発電機は「意思」で立て直せない。設計（慣性・励磁・保護）だけが頼り

━━━━━━━━━━━━━━━━━━━━━━
🔑 送電電力と相差角δ（ki-01の復習と拡張）
━━━━━━━━━━━━━━━━━━━━━━
・同期発電機の送電電力：P＝(EV/X)sinδ（E:発電機内部起電力、V:系統電圧、X:発電機〜系統間の合計リアクタンス、δ:相差角）★
・δ＝90°のとき送電電力が最大（理論上の限界＝定態安定極限電力）
・実運用では最大値よりかなり手前（δの余裕を持たせた）で運転し、外乱が起きても脱調しないようにする
・使いどころ：Xを小さくする・Eを大きくする（強め励磁）ほど、同じδでもより多くの電力を送れる

【図解】P-δ曲線とつまずきの図解
　縦軸に送電電力P、横軸に相差角δをとると、δ＝0°から電力は増加し、δ＝90°で最大値を迎えたあとは減少に転じる山型の曲線になる
　→ 曲線の頂点を超えて負荷が増えると、送電できる電力がむしろ減り、加速度的に脱調へ向かう★
　→ 「頂点の手前で運転する余裕（安定度マージン）」が系統設計の基本思想

━━━━━━━━━━━━━━━━━━━━━━
🔑 定態安定度と過渡安定度
━━━━━━━━━━━━━━━━━━━━━━
・定態安定度：負荷がゆっくり変化したときに、脱調せず新しい平衡点に落ち着けるか（P-δ曲線の頂点までの余裕）
・過渡安定度：短絡事故など急激な外乱が起きたとき、脱調せずに元の同期状態へ戻れるか★
・過渡安定度のほうが厳しい条件（急激な変化）を扱うため、系統設計では過渡安定度がより重視される
・等面積法：過渡安定度の判定に使う考え方。加速側の面積と減速側の面積のバランスで脱調するかを判定する概念

【図解】等面積法のイメージ
　事故発生（δ急増、加速面積が発生）→事故除去（発電機が減速を始める）
　加速で得たエネルギー（面積A1）＜減速で吸収できるエネルギー（面積A2）なら安定を保てる
　→ 「事故を早く除去する（高速遮断）ほどA1が小さくなり安定を保ちやすい」★
　→ 高速遮断器・高速再閉路が安定度向上策として最重要視される理由がここにある

━━━━━━━━━━━━━━━━━━━━━━
🔑 安定度向上策
━━━━━━━━━━━━━━━━━━━━━━
・系統側のリアクタンスXを減らす：直列コンデンサの挿入・多回線化（並列本数を増やす）・電線の多導体化★
・保護・遮断を高速化：高速保護継電器・高速遮断器・高速再閉路（事故除去時間を短縮）
・励磁を高速に：速応励磁方式で発電機の内部起電力Eを素早く回復させる
・発電機の慣性を大きくする：フライホイール効果で回転の急変を緩和（近年は逆にインバータ電源の低慣性が課題）
・系統分割：事故の影響範囲を限定し、他の健全な系統への波及を防ぐ

【図解】安定度向上策の分類マップ
　Xを下げる：直列コンデンサ・多回線化・多導体化
　時間を短くする：高速保護・高速遮断・高速再閉路
　Eを保つ：速応励磁
　→ 「P＝(EV/X)sinδの式のどの文字を有利にするか」で施策を整理すると覚えやすい★

━━━━━━━━━━━━━━━━━━━━━━
🔑 系統分離・脱調と自動制御
━━━━━━━━━━━━━━━━━━━━━━
・脱調：発電機が同期速度から外れ、系統と足並みが合わなくなる現象（大規模停電の引き金になりうる）
・系統分離（解列）：脱調が避けられない場合、被害拡大を防ぐため意図的に系統を切り離す最終手段
・周波数低下時の緊急対策：UFR（周波数低下継電器）による負荷遮断（需要側を強制的に減らして需給を合わせる）★
・広域的な監視：PMU（位相計測装置）等での系統監視、広域機関（OCCTO・de-04既出）による調整

━━━━━━━━━━━━━━━━━━━━━━
🔑 再エネ大量連系と低慣性化の課題
━━━━━━━━━━━━━━━━━━━━━━
○背景：太陽光・風力（インバータ電源）は同期発電機のような回転体の慣性を持たない
・慣性が小さいと、電源脱落時の周波数変化率（RoCoF）が急峻になり、周波数低下継電器が誤って広範囲に動作するリスクがある★
・対策：疑似慣性制御（インバータが慣性のように振る舞う制御）・蓄電池による瞬動的な調整力の確保
・使いどころ：de-04の内容と接続して「再エネ大量導入時代の安定度課題」として記述問題化しやすい

━━━━━━━━━━━━━━━━━━━━━━
★ここだけ暗記
━━━━━━━━━━━━━━━━━━━━━━
★P＝(EV/X)sinδ。δ＝90°が理論上の限界、実運用は手前で余裕を確保
★定態安定度＝緩やかな変化への耐性、過渡安定度＝急激な事故への耐性（より厳しい）
★安定度向上：Xを下げる（直列コンデンサ・多回線化）、時間を短く（高速遮断・再閉路）、Eを保つ（速応励磁）
★等面積法：事故除去が早いほど加速面積が小さく安定を保ちやすい
★インバータ電源は低慣性→RoCoF急峻化が新たな安定度課題`,
