・原因：エアコン・冷蔵庫等の温度制御機器が、停電中に設定温度から外れており、復電の瞬間に一斉に起動しようとするため★
・対策：段階的な復電（エリアを分けて時間差をつけて電力を戻す）で、負荷の集中投入を避ける
