・条件を満たさずに投入すると、大きな突入電流や機械的衝撃で発電機・設備を損傷しかねない
・使いどころ：平常時の発電機併入も、ブラックアウトからの復旧時の系統統合も、根底にある技術（同期投入）は共通している★

