・単巻変圧器：巻線の一部を一次・二次で共用（分路巻線＋直列巻線）
　○利点：小型・軽量・高効率・電圧変動小（自己容量＜負荷容量）
　×欠点：一次二次が絶縁されていない⚠（感電・異常電圧が直通）
・負荷時タップ切換変圧器：無停電で巻数比を変え系統電圧を調整
・計器用変成器（VT・CT）も変圧器の応用（電力科目と共通）

