・使いどころ：「相数・整流方式が増えるほど脈動（リプル）が減る」という傾向をまず押さえる

【図解】整流方式ごとの脈動の目安
　単相半波：脈動大（山が1つ/周期）
　単相全波：脈動中（山が2つ/周期）
