・降圧チョッパ・昇圧チョッパは電圧の向きも電流の向きも一方向（1象限運転）
・電気車（電車）などは力行（加速）と回生（減速で発電）の両方が必要→双方向に電力をやり取りできる構成が要る
・双方向チョッパ：2つのスイッチを組合わせ、力行時は降圧チョッパ・回生時は昇圧チョッパとして動作する構成が代表例★
・使いどころ：「回生ブレーキで発生した電力を架線に戻す」という電気車の仕組みの回路的な裏付け

