○放電加工の利点：硬い材料の加工が可能・機械的な力がかからない・複雑形状に対応
○電解加工の利点：工具電極が摩耗しにくい・熱影響がほとんどない
○TIGと消耗電極式の違い：TIGは電極が溶けない（非消耗）、被覆アーク・CO2溶接は電極（ワイヤ）が溶けて母材になる（消耗電極式）★
○抵抗溶接の原理：ジュール熱による接触部の溶融接合
×誤答肢の典型：「放電加工は加工物に大きな機械的な力がかかる」（実際はほぼ非接触でかからない）
