━━━━━━━━━━━━━━━━━━━━━━
・施設場所と工事方法の適合が原則（展開した場所・点検できる隠ぺい場所・点検できない隠ぺい場所×乾燥・湿気）
・ほぼどこでも施設できる万能工事：金属管工事・合成樹脂管工事（CD管は直接コンクリート埋込み等に限定）・ケーブル工事・2種金属製可とう電線管工事★
