　○系統接地：混触時の電位上昇抑制（変圧器低圧側＝B種）
　○機能接地：避雷器・計器用変成器の動作確保（A種・D種）
・移動して使う機器：接地極付きコンセント＋接地線入りキャブタイヤケーブルで接地を確保
・水気のある場所：漏電遮断器の設置が原則（接地との二段構え）★

【図解】接地3目的の対応マップ
　保安接地（C・D種）：機器外箱→漏電時の感電防止
　系統接地（B種）：変圧器低圧側→混触時の電位上昇抑制
　機能接地（A種等）：避雷器・変成器→保護装置の確実な動作
