・遮断器の保守：接点の摩耗・絶縁油やSF6ガスの状態確認・動作時間の測定
・保護協調の年次確認：系統構成の変更（設備増設等）に応じて整定値の見直しが必要になることがある★
・使いどころ：「設備を増設したら保護協調も見直す」という当たり前だが見落としやすい実務ポイント

