━━━━━━━━━━━━━━━━━━━━━━
・接続部の緩みや劣化は局所的な発熱として現れることが多い
・赤外線サーモグラフィ（無停電で実施可能）：機器を稼働させたまま表面温度を可視化し、異常発熱箇所を早期発見★
・使いどころ：「無停電でできる点検」の代表例として日常・定期点検の枠組みに位置づけられる

